<script lang="ts">import '$lib/design/tokens.css'; import '$lib/components/commerce/store.css'; import { transformStyle } from '$lib/smart-shopping'; let designUrl = $state(''); let error = $state(''); let dragging = $state(false); let transform = $state({ x: 50, y: 50, scale: 1, rotation: 0, opacity: 0.8 }); let stage: HTMLDivElement; function choose(event: Event) { const file = (event.currentTarget as HTMLInputElement).files?.[0]; error = ''; if (!file) return; if (!['image/jpeg','image/png','image/webp'].includes(file.type) || file.size > 5 * 1024 * 1024) { error = 'فقط JPEG، PNG یا WebP تا ۵ مگابایت پذیرفته می‌شود.'; return; } if (designUrl) URL.revokeObjectURL(designUrl); designUrl = URL.createObjectURL(file); } function move(event: PointerEvent) { if (!dragging || !designUrl) return; const r = stage.getBoundingClientRect(); transform = { ...transform, x: Math.max(0, Math.min(100, ((event.clientX-r.left)/r.width)*100)), y: Math.max(0, Math.min(100, ((event.clientY-r.top)/r.height)*100)) }; } function reset() { if (designUrl) URL.revokeObjectURL(designUrl); designUrl=''; error=''; transform={x:50,y:50,scale:1,rotation:0,opacity:.8}; }</script>
<svelte:head><title>شبیه‌ساز طرح تتو | اینکورا</title><meta name="robots" content="noindex,nofollow" /></svelte:head><div class="inkora-theme inkora-store smart-page" dir="rtl"><header class="store-header"><div class="store-container store-header-inner"><a class="store-brand" href="/"><img src="/assets/brand/inkora-wordmark-temporary.svg" alt="اینکورا؛ نوشتار موقت برند" /></a><nav class="store-nav" aria-label="ناوبری"><a href="/advisor">انتخاب‌گر</a><a href="/compare">مقایسه</a><a href="/simulator" aria-current="page">شبیه‌ساز</a></nav></div></header><main class="store-container store-main"><p class="eyebrow">فقط در مرورگر شما</p><h1>پیش‌نمایش دو‌بُعدی طرح</h1><p class="lead">این ابزار هیچ پرونده‌ای را به سرور، WordPress یا AI نمی‌فرستد و ذخیره نمی‌کند. سطح زیر، یک جای‌نگهدار انتزاعی است؛ پیش‌بینی نتیجه روی پوست یا توصیهٔ پزشکی نیست.</p><div class="simulator-layout"><section class="smart-panel simulator-controls"><label for="design">فایل طرح خودتان</label><input id="design" type="file" accept="image/jpeg,image/png,image/webp" onchange={choose} /><p class="empty-copy">JPEG، PNG یا WebP، حداکثر ۵ مگابایت. فقط فایلی را استفاده کنید که حق استفاده از آن را دارید.</p>{#if error}<p role="alert" class="error-copy">{error}</p>{/if}<label for="scale">اندازه: {transform.scale.toFixed(1)}×</label><input id="scale" type="range" min="0.2" max="2.5" step="0.1" bind:value={transform.scale} /><label for="rotation">چرخش: {transform.rotation}°</label><input id="rotation" type="range" min="-180" max="180" step="1" bind:value={transform.rotation} /><label for="opacity">شفافیت: {Math.round(transform.opacity*100)}٪</label><input id="opacity" type="range" min="0.1" max="1" step="0.05" bind:value={transform.opacity} /><button class="button" onclick={reset}>پاک‌سازی و بازنشانی</button></section><section><div class="simulator-stage" bind:this={stage} onpointermove={move} onpointerup={() => dragging=false} onpointercancel={() => dragging=false} role="application" aria-label="سطح جای‌نگهدار؛ برای جابه‌جایی طرح، آن را بکشید.">{#if designUrl}<img class="design-overlay" src={designUrl} alt="پیش‌نمایش فایل طرح انتخاب‌شده" style={`transform:${transformStyle(transform)};opacity:${transform.opacity}`} onpointerdown={(e) => { dragging=true; (e.currentTarget as HTMLElement).setPointerCapture(e.pointerId); }} />{:else}<p>سطح انتزاعی برای پیش‌نمایش محلی<br /><small>عکس پوست واقعی هنوز با رضایت لازم دریافت نشده است.</small></p>{/if}</div><p class="empty-copy">با کشیدن طرح روی سطح، جای آن را تغییر دهید. کنترل‌های range با صفحه‌کلید هم کار می‌کنند.</p></section></div></main></div>
